mkuse!{use crate :: cell :: Cell ;}
mkuse!{use crate :: sync as public ;}
mkuse!{use crate :: sync :: atomic :: Ordering :: { Acquire , Relaxed , Release } ;}
mkuse!{use crate :: sync :: poison :: once :: ExclusiveState ;}
mkuse!{use crate :: sys :: futex :: { Futex , Primitive , futex_wait , futex_wake_all } ;}
mkitem!{# [doc = " No initialization has run yet, and no thread is currently using the Once."] const INCOMPLETE : Primitive = 3 ;}
mkitem!{# [doc = " Some thread has previously attempted to initialize the Once, but it panicked,"] # [doc = " so the Once is now poisoned. There are no other threads currently accessing"] # [doc = " this Once."] const POISONED : Primitive = 2 ;}
mkitem!{# [doc = " Some thread is currently attempting to run initialization. It may succeed,"] # [doc = " so all future threads need to wait for it to finish."] const RUNNING : Primitive = 1 ;}
mkitem!{# [doc = " Initialization has completed and all future calls should finish immediately."] # [doc = " By choosing this state as the all-zero state the `is_completed` check can be"] # [doc = " a bit faster on some platforms."] const COMPLETE : Primitive = 0 ;}
mkitem!{# [doc = " May only be set if the state is not COMPLETE."] const QUEUED : Primitive = 4 ;}
mkitem!{const STATE_MASK : Primitive = 0b11 ;}
mkitem!{mkstruct!{pub struct OnceState { poisoned : bool , set_state_to : Cell < Primitive > , }}}
mkitem!{mkimpl!{impl OnceState { # [inline] pub fn is_poisoned (& self) -> bool { self . poisoned } # [inline] pub fn poison (& self) { self . set_state_to . set (POISONED) ; } }}}
mkitem!{mkstruct!{struct CompletionGuard < 'a > { state_and_queued : & 'a Futex , set_state_on_drop_to : Primitive , }}}
mkitem!{mkimpl!{impl < 'a > Drop for CompletionGuard < 'a > { fn drop (& mut self) { if self . state_and_queued . swap (self . set_state_on_drop_to , Release) & QUEUED != 0 { futex_wake_all (self . state_and_queued) ; } } }}}
mkitem!{mkstruct!{pub struct Once { state_and_queued : Futex , }}}
mkitem!{mkimpl!{impl Once { # [inline] pub const fn new () -> Once { Once { state_and_queued : Futex :: new (INCOMPLETE) } } # [inline] pub fn is_completed (& self) -> bool { self . state_and_queued . load (Acquire) == COMPLETE } # [inline] pub (crate) fn state (& mut self) -> ExclusiveState { match * self . state_and_queued . get_mut () { INCOMPLETE => ExclusiveState :: Incomplete , POISONED => ExclusiveState :: Poisoned , COMPLETE => ExclusiveState :: Complete , _ => unreachable ! ("invalid Once state") , } } # [inline] pub (crate) fn set_state (& mut self , new_state : ExclusiveState) { * self . state_and_queued . get_mut () = match new_state { ExclusiveState :: Incomplete => INCOMPLETE , ExclusiveState :: Poisoned => POISONED , ExclusiveState :: Complete => COMPLETE , } ; } # [cold] # [track_caller] pub fn wait (& self , ignore_poisoning : bool) { let mut state_and_queued = self . state_and_queued . load (Acquire) ; loop { let state = state_and_queued & STATE_MASK ; let queued = state_and_queued & QUEUED != 0 ; match state { COMPLETE => return , POISONED if ! ignore_poisoning => { panic ! ("Once instance has previously been poisoned") ; } _ => { if ! queued { state_and_queued += QUEUED ; if let Err (new) = self . state_and_queued . compare_exchange_weak (state , state_and_queued , Relaxed , Acquire ,) { state_and_queued = new ; continue ; } } futex_wait (& self . state_and_queued , state_and_queued , None) ; state_and_queued = self . state_and_queued . load (Acquire) ; } } } } # [cold] # [track_caller] pub fn call (& self , ignore_poisoning : bool , f : & mut dyn FnMut (& public :: OnceState)) { let mut state_and_queued = self . state_and_queued . load (Acquire) ; loop { let state = state_and_queued & STATE_MASK ; let queued = state_and_queued & QUEUED != 0 ; match state { COMPLETE => return , POISONED if ! ignore_poisoning => { panic ! ("Once instance has previously been poisoned") ; } INCOMPLETE | POISONED => { let next = RUNNING + if queued { QUEUED } else { 0 } ; if let Err (new) = self . state_and_queued . compare_exchange_weak (state_and_queued , next , Acquire , Acquire ,) { state_and_queued = new ; continue ; } let mut waiter_queue = CompletionGuard { state_and_queued : & self . state_and_queued , set_state_on_drop_to : POISONED , } ; let f_state = public :: OnceState { inner : OnceState { poisoned : state == POISONED , set_state_to : Cell :: new (COMPLETE) , } , } ; f (& f_state) ; waiter_queue . set_state_on_drop_to = f_state . inner . set_state_to . get () ; return ; } _ => { assert ! (state == RUNNING) ; if ! queued { state_and_queued += QUEUED ; if let Err (new) = self . state_and_queued . compare_exchange_weak (state , state_and_queued , Relaxed , Acquire ,) { state_and_queued = new ; continue ; } } futex_wait (& self . state_and_queued , state_and_queued , None) ; state_and_queued = self . state_and_queued . load (Acquire) ; } } } } }}}